// Shadcn-inspired Design Variables
// Modern, clean color palette following shadcn/ui conventions

// Base Colors (from shadcn default theme)
$shadcn-background: 0 0% 100%;
$shadcn-foreground: 222.2 84% 4.9%;

$shadcn-card: 0 0% 100%;
$shadcn-card-foreground: 222.2 84% 4.9%;

$shadcn-popover: 0 0% 100%;
$shadcn-popover-foreground: 222.2 84% 4.9%;

$shadcn-primary: 221.2 83.2% 53.3%;
$shadcn-primary-foreground: 210 40% 98%;

$shadcn-secondary: 210 40% 96.1%;
$shadcn-secondary-foreground: 222.2 47.4% 11.2%;

$shadcn-muted: 210 40% 96.1%;
$shadcn-muted-foreground: 215.4 16.3% 46.9%;

$shadcn-accent: 210 40% 96.1%;
$shadcn-accent-foreground: 222.2 47.4% 11.2%;

$shadcn-destructive: 0 84.2% 60.2%;
$shadcn-destructive-foreground: 210 40% 98%;

$shadcn-border: 214.3 31.8% 91.4%;
$shadcn-input: 214.3 31.8% 91.4%;
$shadcn-ring: 221.2 83.2% 53.3%;

$shadcn-radius: 0.5rem;

// Dark mode colors
$shadcn-dark-background: 222.2 84% 4.9%;
$shadcn-dark-foreground: 210 40% 98%;

$shadcn-dark-card: 222.2 84% 4.9%;
$shadcn-dark-card-foreground: 210 40% 98%;

$shadcn-dark-popover: 222.2 84% 4.9%;
$shadcn-dark-popover-foreground: 210 40% 98%;

$shadcn-dark-primary: 217.2 91.2% 59.8%;
$shadcn-dark-primary-foreground: 222.2 47.4% 11.2%;

$shadcn-dark-secondary: 217.2 32.6% 17.5%;
$shadcn-dark-secondary-foreground: 210 40% 98%;

$shadcn-dark-muted: 217.2 32.6% 17.5%;
$shadcn-dark-muted-foreground: 215 20.2% 65.1%;

$shadcn-dark-accent: 217.2 32.6% 17.5%;
$shadcn-dark-accent-foreground: 210 40% 98%;

$shadcn-dark-destructive: 0 62.8% 30.6%;
$shadcn-dark-destructive-foreground: 210 40% 98%;

$shadcn-dark-border: 217.2 32.6% 17.5%;
$shadcn-dark-input: 217.2 32.6% 17.5%;
$shadcn-dark-ring: 224.3 76.3% 48%;

// Helper function to convert HSL to hex (simplified approximation)
@function hsl-to-hex($h, $s, $l) {
  @return unquote("hsl(#{$h}, #{$s}, #{$l})");
}

// Generate hex values for CSS variables
$shadcn-background-hex: hsl-to-hex(0, 0%, 100%);
$shadcn-foreground-hex: hsl-to-hex(222.2, 84%, 4.9%);
$shadcn-primary-hex: hsl-to-hex(221.2, 83.2%, 53.3%);
$shadcn-secondary-hex: hsl-to-hex(210, 40%, 96.1%);
$shadcn-muted-hex: hsl-to-hex(210, 40%, 96.1%);
$shadcn-accent-hex: hsl-to-hex(210, 40%, 96.1%);
$shadcn-destructive-hex: hsl-to-hex(0, 84.2%, 60.2%);
$shadcn-border-hex: hsl-to-hex(214.3, 31.8%, 91.4%);
$shadcn-input-hex: hsl-to-hex(214.3, 31.8%, 91.4%);
$shadcn-ring-hex: hsl-to-hex(221.2, 83.2%, 53.3%);

$shadcn-dark-background-hex: hsl-to-hex(222.2, 84%, 4.9%);
$shadcn-dark-foreground-hex: hsl-to-hex(210, 40%, 98%);
$shadcn-dark-primary-hex: hsl-to-hex(217.2, 91.2%, 59.8%);
$shadcn-dark-secondary-hex: hsl-to-hex(217.2, 32.6%, 17.5%);
$shadcn-dark-muted-hex: hsl-to-hex(217.2, 32.6%, 17.5%);
$shadcn-dark-accent-hex: hsl-to-hex(217.2, 32.6%, 17.5%);
$shadcn-dark-destructive-hex: hsl-to-hex(0, 62.8%, 30.6%);
$shadcn-dark-border-hex: hsl-to-hex(217.2, 32.6%, 17.5%);
$shadcn-dark-input-hex: hsl-to-hex(217.2, 32.6%, 17.5%);
$shadcn-dark-ring-hex: hsl-to-hex(224.3, 76.3%, 48%);

